# ─── CONFIG ──────────────────────────────────────────────────────────────────
SUPABASE_URL = "https://cjozixuffjzaridfrnud.supabase.co"
SUPABASE_KEY = "sb_publishable_7EUyFz_CFk3lf3BPtYpp6A_fU1ik5ZG"

HEADERS = {
    "apikey": SUPABASE_KEY,
    "Authorization": f"Bearer {SUPABASE_KEY}",
    "Content-Type": "application/json",
    "Prefer": "resolution=merge-duplicates,return=minimal",
}

def _upsert(table, rows):
    url = f"{SUPABASE_URL}/rest/v1/{table}"
    for i in range(0, len(rows), 500):
        r = httpx.post(url, headers=HEADERS, json=rows[i:i+500], timeout=30)
        if r.status_code not in (200, 201, 204):
            raise Exception(f"upsert {table} failed {r.status_code}: {r.text[:300]}")

def _delete_all(table, pk="id"):
    url = f"{SUPABASE_URL}/rest/v1/{table}"
    r = httpx.delete(url, headers=HEADERS, params={pk: "neq.-999999"}, timeout=30)
    if r.status_code not in (200, 204):
        raise Exception(f"delete {table} failed {r.status_code}: {r.text[:300]}")

def _count(table, col="id"):
    url = f"{SUPABASE_URL}/rest/v1/{table}"
    h = {**HEADERS, "Prefer": "count=exact"}
    r = httpx.head(url, headers=h, timeout=30)
    cr = r.headers.get("content-range","?/?")
    return cr.split("/")[-1]

