# ─── MIGRATION ────────────────────────────────────────────────────────────────

def clear_tables():
    print("Clearing existing data...")
    _delete_all("project_monthly_data", "id")
    _delete_all("portfolio_monthly_data", "month_idx")
    _delete_all("projects", "id")
    _delete_all("model_config", "id")
    print("  Done")

def insert_projects():
    print("Inserting projects...")
    rows = [{k: v for k,v in p.items() if k not in ("fte","cost","ot","cpmo","pmo","epcm")} for p in PROJECTS]
    _upsert("projects", rows)
    print(f"  {len(rows)} projects inserted")

def insert_project_monthly():
    print("Inserting project monthly data...")
    rows = []
    for p in PROJECTS:
        for i in range(90):
            rows.append({
                "project_id": p["id"],
                "month_idx":  i,
                "model_fte":  p["fte"][i],
                "model_cost": p["cost"][i],
                "asis_fte":   0,
                "asis_cost":  0,
                "ot_fte":     p["ot"][i],
                "cpmo_fte":   p["cpmo"][i],
                "pmo_fte":    p["pmo"][i],
                "epcm_fte":   p["epcm"][i],
            })
    _upsert("project_monthly_data", rows)
    print(f"  {len(rows)} rows inserted")

def insert_portfolio_monthly():
    print("Inserting portfolio monthly data...")
    rows = []
    for i in range(90):
        rows.append({
            "month_idx":       i,
            "model_fte":       MODEL_FTE[i],
            "model_mh":        MODEL_MH[i],
            "model_cost":      MODEL_COST[i],
            "asis_fte":        ASIS_FTE[i],
            "asis_mh":         ASIS_MH[i],
            "asis_cost":       ASIS_COST[i],
            "ot_model_fte":    ENT_MODEL_OT[i],
            "cpmo_model_fte":  ENT_MODEL_CPMO[i],
            "pmo_model_fte":   ENT_MODEL_PMO[i],
            "epcm_model_fte":  ENT_MODEL_EPCM[i],
            "ot_asis_fte":     ENT_ASIS_OT[i],
            "cpmo_asis_fte":   ENT_ASIS_CPMO[i],
            "pmo_asis_fte":    ENT_ASIS_PMO[i],
            "epcm_asis_fte":   ENT_ASIS_EPCM[i],
            "mining_model_fte":   DISC_MINING_MODEL_FTE[i],
            "process_model_fte":  DISC_PROC_MODEL_FTE[i],
            "mining_asis_fte":    DISC_MINING_ASIS_FTE[i],
            "process_asis_fte":   DISC_PROC_ASIS_FTE[i],
            "mining_model_cost":  DISC_MINING_MODEL_COST[i],
            "process_model_cost": DISC_PROC_MODEL_COST[i],
            "mining_asis_cost":   DISC_MINING_ASIS_COST[i],
            "process_asis_cost":  DISC_PROC_ASIS_COST[i],
        })
    _upsert("portfolio_monthly_data", rows)
    print(f"  {len(rows)} rows inserted")

def insert_model_config():
    print("Inserting model config...")
    # All rows must have identical keys for PostgREST batch upsert
    rows = []
    for cfg in MODEL_CONFIG:
        row = {
            "category":   cfg.get("category"),
            "key":        cfg.get("key"),
            "sub_key":    cfg.get("sub_key"),
            "value":      cfg.get("value"),
            "value_json": cfg.get("value_json"),
            "label":      cfg.get("label"),
        }
        rows.append(row)
    _upsert("model_config", rows)
    print(f"  {len(rows)} config items inserted")

def verify():
    print("\nVerification:")
    print(f"  projects:               {_count('projects')} rows")
    print(f"  project_monthly_data:   {_count('project_monthly_data')} rows (expected 1620)")
    print(f"  portfolio_monthly_data: {_count('portfolio_monthly_data', 'month_idx')} rows (expected 90)")
    print(f"  model_config:           {_count('model_config')} rows")

if __name__ == "__main__":
    clear_tables()
    insert_projects()
    insert_project_monthly()
    insert_portfolio_monthly()
    insert_model_config()
    verify()
    print("\nMigration complete ✓")